/**
 * 剧集匹配编排
 * searchEpisodes 为主入口，协调 tmdb、hash、search、fallback
 */

import { corsProxy } from '../user-config.js';
import { lsGetItem, lsKeys } from '../config/api.js';
import { fetchSearchEpisodes } from './search.js';
import { tryMatchByTmdbId } from './tmdb.js';
import { tryMatchByHash } from './hash.js';
import { autoFailback } from './fallback.js';
import {
    getSeasonEpisodeOffset,
    prioritizeSeasonCandidates,
    selectSeasonInfo,
} from './season.js';
import { findCompatibleEpisode } from './episode-number.js';

function hasCompatibleEpisode(animaInfo, expectedEpisodeNumber) {
    return Boolean(
        animaInfo?.animes?.some((anime) =>
            findCompatibleEpisode(anime.episodes, anime.animeId, expectedEpisodeNumber)
        )
    );
}

/**
 * 写入赛季信息到 localStorage
 * @param {string} _season_key
 * @param {object} newSeasonInfo
 */
export function writeLsSeasonInfo(_season_key, newSeasonInfo) {
    if (!_season_key) {
        return console.log('_season_key is undefined, skip');
    }
    let seasonInfoListStr = localStorage.getItem(_season_key);
    let seasonInfoList = [];
    if (seasonInfoListStr) {
        try {
            seasonInfoList = JSON.parse(seasonInfoListStr);
            if (!Array.isArray(seasonInfoList)) seasonInfoList = [];
        } catch (error) {
            console.warn('[赛季缓存] 记录损坏，已重建:', error);
        }
    }
    const existingSeasonInfo = seasonInfoList.find((si) => si.name === newSeasonInfo.name);
    if (!existingSeasonInfo) {
        seasonInfoList.push(newSeasonInfo);
    } else {
        Object.assign(existingSeasonInfo, newSeasonInfo);
    }
    localStorage.setItem(_season_key, JSON.stringify(seasonInfoList));
}

/**
 * 解析 "XXXX SXXEXX" 格式的标题
 * @param {string} animeName
 * @returns {{ title: string, season: number|null, episode: number|null }}
 */
export function parseAnimeName(animeName) {
    const match = animeName.match(/^(.*?)\s*[Ss](\d{1,2})[Ee](\d{1,4})\b/);
    if (match) {
        return {
            title: match[1].replace(/[._]/g, ' ').trim(),
            season: parseInt(match[2], 10),
            episode: parseInt(match[3], 10),
        };
    }
    return { title: animeName, season: null, episode: null };
}

/**
 * 通过赛季缓存匹配
 * @param {string} _season_key
 * @param {number} episode
 * @param {string} prefix
 * @returns {Promise<object|null>}
 */
export async function lsSeasonSearchEpisodes(_season_key, episode, prefix, searchTitle, signal) {
    const seasonInfoListStr = window.localStorage.getItem(_season_key);
    if (!seasonInfoListStr) return null;

    let seasonInfoList;
    try {
        seasonInfoList = JSON.parse(seasonInfoListStr);
    } catch (error) {
        console.warn('[赛季缓存] 记录损坏，已清除:', error);
        window.localStorage.removeItem(_season_key);
        return null;
    }
    const selectedSeasonInfo = selectSeasonInfo(searchTitle, seasonInfoList, episode);

    if (selectedSeasonInfo) {
        const episodeOffset = getSeasonEpisodeOffset(selectedSeasonInfo);
        const newEpisode = Number(episode) + episodeOffset;
        console.log(`命中seasonInfo缓存: ${selectedSeasonInfo.name},偏移量: ${episodeOffset},集: ${newEpisode}`);
        const animaInfo = await fetchSearchEpisodes(
            selectedSeasonInfo.name,
            newEpisode,
            selectedSeasonInfo.apiPrefix || prefix,
            signal
        );
        if (animaInfo?.animes) {
            animaInfo.animes = prioritizeSeasonCandidates(searchTitle, animaInfo.animes);
            const selectedAnimeIndex = animaInfo.animes.findIndex(
                (anime) => anime.animeId == selectedSeasonInfo.animeId
            );
            if (selectedAnimeIndex > 0) {
                animaInfo.animes.unshift(animaInfo.animes.splice(selectedAnimeIndex, 1)[0]);
            }
        }
        return { animaInfo, newEpisode, expectedEpisodeNumber: newEpisode };
    }
    return null;
}

/**
 * 主匹配入口：根据 itemInfoMap 搜索弹幕
 * @param {object} itemInfoMap - 由 getMapByEmbyItemInfo 提供
 * @returns {Promise<object|null>}
 */
export async function searchEpisodes(itemInfoMap, signal) {
    const {
        _season_key,
        animeName,
        episodeName,
        episode,
        seriesOrMovieId,
        streamUrl,
        size,
        duration,
    } = itemInfoMap;

    console.log(`[自动匹配] 标题名: ${episodeName}` + (episode ? `,章节过滤: ${episode}` : ''));

    const apiPriority = lsGetItem(lsKeys.apiPriority.id);
    const apiConfigs = {
        official: {
            name: '官方API',
            prefix: corsProxy + 'https://api.dandanplay.net/api/v2',
            enabled: lsGetItem(lsKeys.useOfficialApi.id),
        },
        custom: {
            name: '自定义API',
            prefix: lsGetItem(lsKeys.customApiPrefix.id),
            enabled: lsGetItem(lsKeys.useCustomApi.id),
        },
    };

    const currentPriority =
        Array.isArray(apiPriority) &&
        apiPriority[0] === 'custom' &&
        apiConfigs.custom.enabled &&
        apiConfigs.custom.prefix?.trim()
            ? 'custom'
            : 'official';
    const selectedApiConfig =
        apiConfigs[currentPriority].enabled && apiConfigs[currentPriority].prefix?.trim()
            ? apiConfigs[currentPriority]
            : apiConfigs.custom;

    const animaRes = await lsSeasonSearchEpisodes(
        _season_key,
        episode,
        selectedApiConfig.prefix,
        animeName,
        signal
    );
    if (
        animaRes?.animaInfo?.animes?.length > 0 &&
        hasCompatibleEpisode(animaRes.animaInfo, animaRes.expectedEpisodeNumber)
    ) {
        console.log(`[自动匹配] 命中赛季缓存，直接使用`);
        return {
            animeOriginalTitle: '',
            animaInfo: animaRes.animaInfo,
            expectedEpisodeNumber: animaRes.expectedEpisodeNumber,
        };
    }

    const tmdbMatchResult = await tryMatchByTmdbId(itemInfoMap, apiConfigs, apiPriority, signal);
    if (tmdbMatchResult) return tmdbMatchResult;

    const hashMatchResult = await tryMatchByHash(
        episodeName,
        episode,
        streamUrl,
        size,
        duration,
        apiConfigs,
        apiPriority,
        signal
    );
    if (hashMatchResult) return hashMatchResult;

    for (const apiKey of apiPriority) {
        const config = apiConfigs[apiKey];
        if (!config || !config.enabled || (apiKey === 'custom' && !config.prefix)) continue;

        let searchTitle = episodeName;
        let searchEpisode = episode;

        if (apiKey === 'official') {
            const parsed = parseAnimeName(episodeName);
            if (parsed.season !== null) {
                searchTitle = parsed.season === 1 ? parsed.title : `${parsed.title} 第${parsed.season}季`;
                searchEpisode = parsed.episode;
                console.log(`[自动匹配][官方API优化] 格式化搜索: 标题='${searchTitle}', 集数=${searchEpisode}`);
            }
        }

        let searchAnimaInfo = await fetchSearchEpisodes(searchTitle, searchEpisode, config.prefix, signal);
        if (
            searchAnimaInfo?.animes?.length > 0 &&
            hasCompatibleEpisode(searchAnimaInfo, searchEpisode)
        ) {
            searchAnimaInfo.animes = prioritizeSeasonCandidates(searchTitle, searchAnimaInfo.animes);
            return {
                animaInfo: searchAnimaInfo,
                apiPrefix: config.prefix,
                expectedEpisodeNumber: searchEpisode,
            };
        }

        searchAnimaInfo = await fetchSearchEpisodes(episodeName, null, config.prefix, signal);
        if (
            searchAnimaInfo?.animes?.length > 0 &&
            hasCompatibleEpisode(searchAnimaInfo, episode)
        ) {
            searchAnimaInfo.animes = prioritizeSeasonCandidates(episodeName, searchAnimaInfo.animes);
            return {
                animaInfo: searchAnimaInfo,
                apiPrefix: config.prefix,
                expectedEpisodeNumber: episode,
            };
        }
    }

    const animaInfo = await fetchSearchEpisodes(animeName, episode, selectedApiConfig.prefix, signal);
    if (animaInfo?.animes?.length > 0 && hasCompatibleEpisode(animaInfo, episode)) {
        animaInfo.animes = prioritizeSeasonCandidates(animeName, animaInfo.animes);
        return { animeOriginalTitle: '', animaInfo, expectedEpisodeNumber: episode };
    }

    return autoFailback(animeName, episode, seriesOrMovieId, selectedApiConfig.prefix, signal);
}
